UPDATE approval_doc
   SET doc_type = #{docType},
       title    = #{title},
       content  = #{content},
       amount   = #{amount}
 WHERE approval_id = #{approvalId}

UPDATE approval_doc
   SET status       = #{status},
       current_step = #{currentStep},
       submitted_at = #{submittedAt},
       completed_at = #{completedAt}
 WHERE approval_id = #{approvalId}

